const chSpriteBoxes=[[153,10,245,478],[513,69,504,416],[1072,108,428,340],[16,576,496,386],[512,522,469,461],[1042,576,476,382]];
function chArt(el,recipe,cropped=false){const r=chronicle.recipes.find(r=>r.id===recipe);if(!r)return;el.classList.add('ch-craft-art');el.style.backgroundImage='url("assets/crafts/handmade-sheet.png")';if(!cropped){el.style.backgroundSize='300% 200%';el.style.backgroundPosition=(r.sprite%3*50)+'% '+(r.sprite>2?'100%':'0%');return}const [x,y,w,h]=chSpriteBoxes[r.sprite];el.style.backgroundSize=1536/w*100+'% '+1024/h*100+'%';el.style.backgroundPosition=x/(1536-w)*100+'% '+y/(1024-h)*100+'%';el.style.aspectRatio=w+'/'+h}
function chSave(){persist();cityDraw()}
function chResult(r,again){if(!r.ok){if($('chFeedback'))$('chFeedback').textContent=r.reason;else{modal('One more thing','<p>'+chEsc(r.reason)+'</p>');if(again)action('Return to this activity',again)}return false}window.EldoriaSound?.cue?.(r.item?'craft':r.coins===100?'bell':'gentle');chSave();modal(r.title||'A little progress','<p>'+chEsc(r.detail||'This moment is saved in your life in Eldoria.')+'</p><p id="chFeedback" role="status"></p>');if(r.item){const art=document.createElement('div');art.className='ch-finished-art';chArt(art,r.item.recipe);$('modal').append(art);action('Open my handmade collection',chCollection)}action('Continue the bonfire adventure',chChapter);if(again)action('Return to this activity',again);action('Enjoy this place',()=>{$('modal').close();cityDraw()});return true}
function chTravel(district,room,then){lifeTravel({district,room},then)}
function chBoard(){const q=chronicle.ensure(state),a=chronicle.current(state),r=chronicle.rhythm(chNow());modal('Eldoria · a county to belong to','<span class="city-eyebrow">'+chEsc(r.title)+'</span><p>'+chEsc(r.text)+'</p><h3>'+chEsc(q.complete?'A gathering that returns':q.started?a.title:'The Bell Beneath the Willow')+'</h3><p>'+chEsc(q.complete?'Your festival tradition lives on: '+q.tradition+'. The circle, your creations and the neighbors remember what you made together.':q.started?a.goal:'Fern has an invitation waiting at the Moonleaf Tavern. A forgotten bell, a handmade festival, and a little midnight magic are about to become your story.')+'</p><progress max="11" value="'+q.step+'" aria-label="Bonfire story progress"></progress><p>'+q.step+' of 11 chapters complete</p><p id="chFeedback" role="status"></p>');if(!q.started)action('Accept Fern’s invitation',()=>chResult(chronicle.start(state,chNow()),chChapter));else if(!q.complete)action('Continue · '+a.title,chChapter);else{action('Return to the festival circle',()=>chTravel('forest','countyCamp',chCamp));action('Elowen’s midnight epilogue',()=>chResult(chronicle.midnight(state,chHere(),chNow()),chBoard))}action('County journal & discoveries',chJournal);action('Find a neighbor · live whereabouts',chNeighbors);action('Design something by hand',()=>chDesign());action('My collection · wear, place, gift or sell',chCollection);action('Daily supplies & commissions',chOrders);action('Close the county book',()=>{$('modal').close();cityDraw()})}
function chChapter(){const q=chronicle.ensure(state),a=chronicle.current(state);if(!q.started){chBoard();return}if(!a){chBoard();return}if(!chronicle.place(chHere(),a.district,a.room)){modal(a.title,'<p>'+chEsc(a.text)+'</p><p><strong>Next:</strong> '+chEsc(a.goal)+'</p><p>Your next chapter is at '+chEsc(a.room?cityRoomNames[a.room]:cityShort[a.district])+'.</p>');action('Travel to this chapter',()=>chTravel(a.district,a.room,chChapter));action('Pause · keep my progress',()=>{$('modal').close();cityDraw()});return}modal(a.title,'<span class="city-eyebrow">CHAPTER '+(q.step+1)+' · '+chEsc(a.person)+'</span><p class="life-dialogue">'+chEsc(a.text)+'</p><p><strong>'+chEsc(a.goal)+'</strong></p><p id="chFeedback" role="status"></p>');if(a.room)lifePhoto(a.room);if(a.task){const actions={tent:['Set up my canvas tent',chTent],lantern:['Design a festival lantern',()=>chDesign('lantern')],cook:['Use my kitchen stove',chCook],harvest:['Tend the individual garden beds',chGarden],letter:['Explore the archive shelves',()=>{$('modal').close();cityDraw();cityMessage('Look for the tiny folded page on the left-hand archive shelves.')}],bell:['Explore the woodland bank',()=>{$('modal').close();cityDraw();cityMessage('Look for a brass glint beside the woodland pool, on dry stone.')}],setup:['Set up the festival clearing',chSetup]};const item=actions[a.task];if(item)action(item[0],item[1]);if(['letter','bell'].includes(a.task)&&q.found[a.task])action('Review the discovery I already found',()=>chResult(chronicle.discover(state,a.task,chHere(),chNow()),chChapter));}else if(Array.isArray(a.answer)){let sequence=[];const line=document.createElement('p');line.id='chStarSequence';line.setAttribute('aria-live','polite');$('modal').append(line);a.choices.forEach((label,i)=>{const b=action(label,()=>{sequence.push(i);line.textContent=sequence.map(n=>a.choices[n]).join(' → ');if(sequence.length===a.answer.length){const r=chronicle.answer(state,q.step,sequence,chHere(),chNow());if(!chResult(r,chChapter)){sequence=[];line.textContent=''}}});b.dataset.chStar=i});action('Start the constellation again',()=>{sequence=[];line.textContent=''})}else a.choices.forEach((label,i)=>{const expected=q.step,b=action(label,()=>chResult(chronicle.answer(state,expected,i,chHere(),chNow()),chChapter));b.dataset.chStoryChoice=i});action('Pause · keep my progress',()=>{$('modal').close();cityDraw()})}
function chSequence(title,text,labels,submit){modal(title,'<p>'+chEsc(text)+'</p><div id="chSequence" aria-live="polite"></div><p id="chFeedback" role="status"></p>');let selected=[];labels.forEach((label,i)=>{const b=action(label,()=>{selected.push(i);$('chSequence').textContent=selected.map(n=>labels[n]).join(' → ');if(selected.length===labels.length){const r=submit(selected);if(!chResult(r,()=>chSequence(title,text,labels,submit))){selected=[];$('chSequence').textContent=''}}});b.dataset.chSequence=i});action('Clear these steps',()=>{selected=[];$('chSequence').textContent=''});action('Leave this activity',()=>{$('modal').close();cityDraw()})}
function chTent(){if(!chronicle.place(chHere(),'forest','countyCamp')){chTravel('forest','countyCamp',chTent);return}chSequence('Your own canvas tent','Choose level dry ground, lay the groundsheet, raise the canvas, then secure every line. Your tent will remain pitched.', ['Survey the dry ground','Lay the groundsheet','Raise the canvas','Secure the lines'],a=>chronicle.interact(state,'tent',a,chHere(),chNow()))}
function chSetup(){if(!chronicle.place(chHere(),'forest','countyCamp')){chTravel('forest','countyCamp',chSetup);return}chSequence('Make a place in the clearing','Lay the table, hang your handmade lantern, then welcome the guests. Your tent and supper should already be ready.', ['Lay the table','Hang my lantern','Welcome the guests'],a=>chronicle.interact(state,'setup',a,chHere(),chNow()))}
function chCook(){if(!chronicle.place(chHere(),'home','cottageKitchen')){chTravel('home','cottageKitchen',chCook);return}modal('At your kitchen stove','<p>Welcome stew: add <strong>vegetables → broth → herbs</strong>. Keep the stove at a gentle simmer, between 25 and 55. One herb portion is used.</p><div id="chCookScene"><div id="chPot" tabindex="0" aria-label="Cooking pot. Add ingredients using their buttons or drag them here.">Your cooking pot</div><div id="chIngredients"></div></div><label for="chHeat">Stove heat <output id="chHeatValue">40</output></label><input id="chHeat" type="range" min="0" max="100" value="40"><p id="chCookContents" aria-live="polite">The pot is empty.</p><p id="chFeedback" role="status"></p>');let ingredients=[];const add=id=>{if(ingredients.length>=3){$('chFeedback').textContent='The pot has its three additions. Empty it to begin again.';return}ingredients.push(id);$('chCookContents').textContent=ingredients.join(' → ');$('chPot').dataset.filled=String(ingredients.length)};for(const id of ['vegetables','broth','herbs']){const b=document.createElement('button');b.textContent=atCap(id);b.draggable=true;b.dataset.chIngredient=id;b.onclick=()=>add(id);b.ondragstart=e=>e.dataTransfer.setData('text/plain',id);$('chIngredients').append(b)}$('chPot').ondragover=e=>e.preventDefault();$('chPot').ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(['vegetables','broth','herbs'].includes(id))add(id)};$('chHeat').oninput=()=>{$('chHeatValue').value=$('chHeat').value;$('chPot').style.setProperty('--simmer',Number($('chHeat').value)/100)};action('Simmer my welcome stew',()=>chResult(chronicle.interact(state,'cook',{ingredients,heat:Number($('chHeat').value)},chHere(),chNow()),chCook));action('Empty the pot',()=>{ingredients=[];$('chCookContents').textContent='The pot is empty.';$('chPot').dataset.filled='0'});action('Leave the stove',()=>{$('modal').close();cityDraw()})}
function chGarden(){if(!chronicle.place(chHere(),'home','cottageYard')&&!chronicle.place(chHere(),'gardens','garden')){chTravel('home','cottageYard',chGarden);return}const q=chronicle.ensure(state);modal('Six little garden beds','<p>Each bed can be planted, watered and harvested separately. Growth takes one real minute after watering. At real midnight, the county’s garden magic brings it to its finest form immediately.</p><div id="chGardenBeds"></div><p id="chFeedback" role="status"></p>');q.beds.forEach((bed,i)=>{const card=document.createElement('article');card.className='ch-bed';const title=document.createElement('h3');title.textContent='Bed '+(i+1);const info=document.createElement('p');info.dataset.chBedClock=i;const next=!bed.crop?'plant':!bed.watered?'water':'harvest';const b=document.createElement('button');b.textContent=next==='plant'?'Plant '+(i%2?'tulips':'vegetables'):next==='water'?'Water this bed':'Harvest this bed';b.dataset.chBed=i;b.onclick=()=>{const r=chronicle.garden(state,i,next,chHere(),chNow());if(r.ok){chSave();chGarden()}else $('chFeedback').textContent=r.reason};card.append(title,info,b);if(bed.crop){const sprout=document.createElement('div');sprout.className='ch-growing-plant';sprout.setAttribute('aria-hidden','true');card.prepend(sprout)}$('chGardenBeds').append(card)});chGardenClocks();action('Return to the garden',()=>{$('modal').close();cityDraw()})}
function chGardenClocks(){for(const el of document.querySelectorAll('[data-ch-bed-clock]')){const b=chronicle.ensure(state).beds[Number(el.dataset.chBedClock)];el.textContent=!b.crop?'Ready for a beginning':!b.watered?atCap(b.crop)+' · needs water':Date.now()>=b.ready?atCap(b.crop)+' · ready to harvest':atCap(b.crop)+' · '+Math.ceil((b.ready-Date.now())/1000)+' seconds to grow'}}
function chDesign(id){const q=chronicle.ensure(state),r=chronicle.recipes.find(r=>r.id===id)||chronicle.recipes[0];modal('Design & make · '+r.name,'<p>Your own name, thread accent and making process become part of this creation. Perfect work made during real midnight carries extra fortune.</p><label for="chRecipe">What shall I make?</label><select id="chRecipe">'+chronicle.recipes.map(x=>'<option value="'+x.id+'"'+(x.id===r.id?' selected':'')+'>'+chEsc(x.name)+'</option>').join('')+'</select><div id="chDesignArt"></div><label for="chDesignName">My creation’s name</label><input id="chDesignName" maxlength="40" value="'+chEsc(r.name)+'"><label for="chDesignColor">Thread accent</label><select id="chDesignColor">'+Object.keys(chronicle.colors).map(x=>'<option>'+x+'</option>').join('')+'</select><p>Materials: '+Object.entries(r.materials).map(([k,n])=>n+' '+k+' ('+(q.materials[k]||0)+' owned)').join(' · ')+'</p><p>Workplace: '+chEsc(cityRoomNames[r.room])+'</p><p id="chFeedback" role="status"></p>');chArt($('chDesignArt'),r.id);$('chRecipe').onchange=()=>chDesign($('chRecipe').value);$('chDesignColor').onchange=()=>{$('chDesignArt').style.borderColor=chronicle.colors[$('chDesignColor').value]};action('Begin making this design',()=>{const name=$('chDesignName').value,color=$('chDesignColor').value;if(!chronicle.place(chHere(),r.district,r.room)){modal('Take this design to its workbench','<p>'+chEsc(r.name)+' is made in '+chEsc(cityRoomNames[r.room])+'. Your design choices are kept for this trip.</p>');action('Travel to my workbench',()=>chTravel(r.district,r.room,()=>chMake(r.id,color,name)));return}chMake(r.id,color,name)});action('My handmade collection',chCollection);action('Collect supplies or see commissions',chOrders)}
function chMake(id,color,name){const r=chronicle.recipes.find(r=>r.id===id);if(!r)return;chSequence('Making '+name,'Complete the stages in order. The material is yours to shape; its finished name and accent will stay in your collection.',r.steps,a=>chronicle.create(state,id,color,name,a,chHere(),chNow()));const art=document.createElement('div');art.className='ch-making-art';chArt(art,id);$('chSequence').before(art)}
function chCollection(){const q=chronicle.ensure(state);modal('Made by my own hands','<p>Keep a creation, display it in a room, wear shoes or a shawl at your bedroom wardrobe, give it to a neighbor who is here, or take it to the merchant.</p><div id="chCollectionGrid"></div><p id="chFeedback" role="status"></p>');const owned=q.items.filter(i=>!i.sold);if(!owned.length)$('chCollectionGrid').innerHTML='<p>Your first handmade creation will appear here.</p>';for(const item of owned){const r=chronicle.recipes.find(r=>r.id===item.recipe),card=document.createElement('article');card.className='ch-item';const art=document.createElement('div');chArt(art,item.recipe);const title=document.createElement('h3');title.textContent=item.name;const text=document.createElement('p');text.textContent=item.quality+' · '+item.color+' accent · '+(item.location==='gift'?'given to '+(elfPopulation.find(p=>p.id===item.owner)?.name||item.owner):item.location);card.append(art,title,text);const add=(label,kind,target,person)=>{const b=document.createElement('button');b.textContent=label;b.dataset.chItemAction=kind;b.dataset.chItem=item.id;b.onclick=()=>chResult(chronicle.itemAction(state,item.id,kind,target,chHere(),chNow(),person),chCollection);card.append(b)};if(item.location!=='gift'){if(r.wear)add('Wear at my wardrobe','wear');add('Display in this room','place');if(item.location!=='bag')add('Pack into my bag','pack');add('Sell at the merchant','sell');for(const person of (item.location==='bag'?chPeopleHere():[]))add('Give to '+person.name,'gift',person.id,person)}$('chCollectionGrid').append(card)}action('Make another design',()=>chDesign());action('Visit my bedroom wardrobe',()=>chTravel('home','cottageBedroom',chCollection));action('Return to the county book',chBoard)}
function chOrders(){const q=chronicle.ensure(state),c=chNow();modal('Supplies & the makers’ counter','<p>Your balance: '+state.coins+' mooncoins. The supply parcel refreshes after real midnight. Each handmade design has one paid commission per real date.</p><p>'+Object.entries(q.materials).map(([id,n])=>chEsc(id)+': '+n).join(' · ')+'</p><p id="chFeedback" role="status"></p>');action('Collect today’s supply parcel',()=>chResult(chronicle.supplies(state,chNow()),chOrders));for(const r of chronicle.recipes){const filled=q.daily[c.key+':order:'+r.id],b=action((filled?'✓ Filled · ':'Deliver · ')+r.name+' · '+(r.price+15+(q.tradition==='makers'?10:0))+' coins',()=>{if(!chronicle.place(chHere(),'market','merchant')){chTravel('market','merchant',chOrders);return}chResult(chronicle.commission(state,r.id,chHere(),chNow()),chOrders)});b.disabled=!!filled}action('Open my designs',()=>chDesign());action('Return to the county book',chBoard)}
function chPeopleHere(){const c=chNow();return elfPopulation.filter(p=>{const l=chronicle.schedule(p,c,state);return l.district===scene&&l.room===cityInside&&!cityTreehousePorch})}
function chNeighbors(){const c=chNow();modal('The county is going about its day','<p>These whereabouts follow Eldoria’s real local clock. A night-view preview changes the light, not anyone’s appointment.</p><div id="chWhereabouts"></div>');for(const person of elfPopulation){const l=chronicle.schedule(person,c,state),card=document.createElement('article');card.className='ch-neighbor';const title=document.createElement('strong');title.textContent=person.name;const text=document.createElement('p');text.textContent=l.activity+' · '+(l.room?cityRoomNames[l.room]:cityShort[l.district]);const b=document.createElement('button');b.textContent='Find '+person.name;b.dataset.chFind=person.id;b.onclick=()=>chTravel(l.district,l.room,()=>elfTalk(person.id));card.append(title,text,b);$('chWhereabouts').append(card)}action('Return to the county book',chBoard)}
function chJournal(){const q=chronicle.ensure(state);modal('The county remembers','<p>'+q.journal.length+' remembered moments · '+Object.keys(q.found).length+' discoveries</p><div id="chJournalEntries"></div>');for(const entry of q.journal){const a=document.createElement('article');a.className='ch-journal-entry';const title=document.createElement('h3');title.textContent=entry.title;const text=document.createElement('p');text.textContent=entry.text;const day=document.createElement('small');day.textContent=entry.day;a.append(title,text,day);$('chJournalEntries').append(a)}if(!q.journal.length)$('chJournalEntries').innerHTML='<p>Your first invitation will begin this book.</p>';action('Continue the bonfire adventure',chChapter);action('Return to the county book',chBoard)}
function chCamp(){const q=chronicle.ensure(state);modal('Embermere · a place around the fire','<p>'+chEsc(q.complete?'Your '+q.tradition+' tradition has become part of the county. The bell, supper table and quiet tent remain ready for another gathering.':'Your preparations are becoming a place the county can share.')+(['rain','sleet','thunderstorm','snowstorm','blizzard'].includes(chNow().weather)?' The guests are gathering under the covered pavilion tonight.':'')+'</p><p id="chFeedback" role="status"></p>');action('Continue the bell’s story',chChapter);action('Set up my canvas tent',chTent);action('Arrange the festival clearing',chSetup);action('Sit beside the fire',()=>chSit());action('Display something I made',chCollection);action('Old camping activities & seasonal gatherings',countyCampMenu);if((state.life?.bag?.['woodland stew']||0)>0)action('Share the welcome circle’s supper',()=>chResult(EldoriaCountyModel.eat(state,'woodland stew',true,chHere(),chNow()),chCamp));if(q.complete)action('Host today’s return gathering',()=>chResult(chronicle.gathering(state,chHere(),chNow()),chCamp));if(q.complete)action('Elowen’s midnight epilogue',()=>chResult(chronicle.midnight(state,chHere(),chNow()),chCamp))}
