const chPresentBefore=neighborhood.present;neighborhood.present=function(id,c){const h=neighborhood.home(id),person=elfPopulation.find(p=>p.id===elves.key(h?.person||''));return person?chronicle.schedule(person,c,state).room===id:chPresentBefore(id,c)};
const chMomentBefore=neighborhood.moment;neighborhood.moment=function(s,id,kind,w,c){const r=chMomentBefore(s,id,kind,w,c);if(r.ok&&!neighborhood.present(id,c))r.detail='Your note and kindness wait beside the door while your neighbor is out.';return r};
