// A neighbor is in one physical place at a time. Directory travel follows the live location.
elfHere=function(){const here=chPeopleHere();if(cottageRoom(cityInside)&&cityInside!=='cottageSitting')return[];return elfDiverse(here,4)};
const chElfTalkBefore=elfTalk;elfTalk=function(id,travel=false){const person=elfPopulation.find(p=>p.id===id);if(!person)return;const l=chronicle.schedule(person,chNow(),state);if(travel&&(scene!==l.district||cityInside!==l.room)){chTravel(l.district,l.room,()=>elfTalk(id));return}chElfTalkBefore(id,false);const q=chronicle.ensure(state),memory=document.createElement('p');memory.className='life-dialogue';memory.textContent=q.memories[id]?'“'+q.memories[id]+'”':l.activity; $('modal').append(memory);action('A favor for '+person.name,()=>{const stage=q.favors[id]||0;if(stage>=2){modal('A promise remembered','<p>'+chEsc(q.memories[id])+'</p>');action('Back to our conversation',()=>elfTalk(id));return}modal('A little help for '+person.name,'<p>'+chEsc(stage===0?'“Would you make something with your own hands for the gathering? Something small, but made with care.”':'“I remember your promise. Bring one of your creations and give it to me while we are together.”')+'</p><p id="chFeedback" role="status"></p>');action(stage===0?'Promise a handmade gift':'Remember the gift I brought',()=>chResult(chronicle.favor(state,id,stage===0?'ask':'deliver',chHere(),chNow(),person),()=>elfTalk(id)));action('Choose a handmade gift',chCollection)});action('Give something from my handmade collection',chCollection)};
const chPeopleBefore=cityBuildPeople;cityBuildPeople=function(){chPeopleBefore();$('cityPeople').replaceChildren();const here=chPeopleHere();for(const person of here){const b=document.createElement('button');b.className='city-person';const gift=chronicle.ensure(state).items.find(i=>i.location==='gift'&&i.owner===person.id&&!i.sold);b.textContent=person.name+' · '+person.role+(gift?' · using '+gift.name:'');b.onclick=()=>elfTalk(person.id);$('cityPeople').append(b)}const find=document.createElement('button');find.className='city-person';find.textContent=here.length?'Find another neighbor':'Neighbors are elsewhere · find them';find.onclick=chNeighbors;$('cityPeople').append(find)};
