const chHotspotsBefore=cityBuildHotspots;cityBuildHotspots=function(){chHotspotsBefore();if(cityInside==='countyCamp')for(const b of $('cityHotspots').querySelectorAll('.work'))b.remove();const q=chronicle.ensure(state),current=chronicle.current(state);for(const d of chronicle.discoveries){if(!chronicle.place(chHere(),d.district,d.room)||cityTreehousePorch||(q.found[d.id]&&current?.task!==d.id))continue;const b=cityTarget('✦',d.x,d.y,()=>chResult(chronicle.discover(state,d.id,chHere(),chNow()),chChapter),'ch-discovery');b.setAttribute('aria-label','Investigate '+d.name);b.title=d.name;b.dataset.chDiscovery=d.id}const targets={cottageKitchen:['Stove',18,50,chCook],cottageSitting:['Sit',68,68,chSit],cottagePorch:['Sit',62,68,chSit],cottageYard:['Beds',44,68,chGarden],garden:['Beds',34,70,chGarden],cottageDen:['Make',27,65,()=>chDesign('shawl')],cottageBedroom:['Wardrobe',90,45,chCollection],countyCamp:['Tent',22,46,chTent],craft:['Make',31,48,()=>chDesign()],originalShop:['Make',44,60,()=>chDesign('shoes')]};const target=targets[cityInside];if(target){const [name,x,y,fn]=target,b=cityTarget(name,x,y,fn,'ch-object');b.setAttribute('aria-label','Use '+name.toLowerCase());b.dataset.chPhysical=name.toLowerCase()}if(cityInside==='countyCamp'){const fire=cityTarget('Bonfire',48,66,chCamp,'ch-object');fire.setAttribute('aria-label','Use bonfire circle');const cooking=cityTarget('Cook',84,54,()=>countyCampActivity('stew'),'ch-object');cooking.setAttribute('aria-label','Use campfire cooking table')}};
const chActionsBefore=cityBuildActions;cityBuildActions=function(){chActionsBefore();const q=chronicle.ensure(state),a=chronicle.current(state);if(q.started&&a&&chronicle.place(chHere(),a.district,a.room))cityCard('The Bell Beneath the Willow',a.goal,'Continue the bonfire adventure',chChapter,'✦');if(['craft','cottageDen','cottageSitting','cottageYard'].includes(cityInside))cityCard('Make something that stays yours','Name your work, choose its accent, and use, display, gift or sell the finished creation.','Open my design bench',()=>chDesign(),'◇');if(cityInside==='merchant')cityCard('A buyer for handmade work','Deliver a daily commission or sell a creation from your bag.','Open county commissions',chOrders,'◇');if(cityInside==='countyCamp')cityCard('A place around the fire','Your festival, your tent, and the county’s remembered welcome.','Open the bonfire circle',chCamp,'✦')};
function chDrawProps(){chProps.replaceChildren();const q=chronicle.ensure(state),shown=q.items.filter(i=>!i.sold&&((i.location===cityInside&&i.location!=='bag'&&i.location!=='worn')||(i.location==='gift'&&chPeopleHere().some(p=>p.id===i.owner)))).slice(-5),positions=cityInside==='cottageYard'?[[75,87],[30,84],[55,92],[17,90],[84,78]]:cityInside==='countyCamp'?[[30,77],[73,86],[45,88],[16,89],[84,84]]:[[44,61],[71,72],[23,83],[82,86],[50,89]];shown.forEach((item,i)=>{const prop=document.createElement('button');prop.className='ch-room-prop';prop.dataset.chProp=item.id;prop.setAttribute('aria-label',item.name+(item.location==='gift'?' · in use by '+(elfPopulation.find(p=>p.id===item.owner)?.name||item.owner):' · handmade furnishing'));chArt(prop,item.recipe,true);const setting=cityInside==='countyCamp'?{lantern:[12,65],quilt:[23,78],shawl:[30,72],planter:[85,94],bench:[53,96],shoes:[43,96]}:null;const [x,y]=setting?.[item.recipe]||positions[i],width=item.recipe==='bench'?30:item.recipe==='lantern'?7:15;prop.style.left=x+'%';prop.style.top=y+'%';prop.style.width=width+'%';prop.onclick=chCollection;chProps.append(prop)});if((q.prepared||q.complete)&&cityInside==='countyCamp'){const line=document.createElement('div');line.className='ch-festival-lights';line.setAttribute('aria-hidden','true');for(let i=0;i<9;i++){const lamp=document.createElement('i');lamp.style.left=8+i*10+'%';lamp.style.top=8+Math.sin(i/8*Math.PI)*9+'%';line.append(lamp)}chProps.append(line);if(!shown.some(i=>i.recipe==='lantern')){const lamp=document.createElement('div');lamp.className='ch-room-prop';chArt(lamp,'lantern',true);Object.assign(lamp.style,{left:'12%',top:'65%',width:'7%'});chProps.append(lamp)}}}
function chTrackerDraw(){const q=chronicle.ensure(state),a=chronicle.current(state),r=chronicle.rhythm(chNow());chTracker.replaceChildren();const content=document.createElement('div'),eyebrow=document.createElement('small');eyebrow.textContent=r.title;const title=document.createElement('h3');title.textContent=q.complete?'The festival lives on · '+q.tradition:q.started?a.title:'The Bell Beneath the Willow';const text=document.createElement('p');text.textContent=q.complete?'Your choices, creations and friendships are part of the county now.':q.started?a.goal:'Fern has an invitation for you. A forgotten bell and a gathering worth making await.';const b=document.createElement('button');b.textContent=q.started&&!q.complete?'Continue my adventure':'Open the county book';b.onclick=q.started&&!q.complete?chChapter:chBoard;content.append(eyebrow,title,text);chTracker.append(content,b);const worn=q.items.filter(i=>i.location==='worn'&&!i.sold);if(worn.length){const outfit=document.createElement('p');outfit.className='ch-outfit';outfit.textContent='Wearing: '+worn.map(i=>i.name).join(' · ');chTracker.append(outfit)}}
const chDrawBefore=cityDraw;cityDraw=function(){chDrawBefore();chTrackerDraw();chDrawProps();$('cityScene').dataset.festival=chronicle.ensure(state).complete?'complete':chronicle.ensure(state).prepared?'ready':'preparing'};comfortDraw=cityDraw;
let chScheduleKey='';function chTick(){chGardenClocks();const c=chNow(),key=c.key+':'+c.hour+':'+chronicle.ensure(state).prepared;if(key!==chScheduleKey){chScheduleKey=key;elfLastView='';elfDraw();chTrackerDraw()}}
window.ELDORIA_CHRONICLE={version:1,open:chBoard,chapter:chChapter,design:chDesign,collection:chCollection,neighbors:chNeighbors,journal:chJournal,garden:chGarden,cook:chCook,tent:chTent,setup:chSetup,get progress(){return structuredClone(chronicle.ensure(state))},get schedules(){return elfPopulation.map(p=>({id:p.id,name:p.name,...chronicle.schedule(p,chNow(),state)}))}};
chTick();cityDraw();persist();setInterval(chTick,1000);
